<script setup lang="ts">const year=new Date().getFullYear();const {settings,loadSettings}=usePublicContent();await loadSettings();const phoneHref=(phone:string)=>`tel:+351${phone.replace(/\D/g,'')}`</script><template><footer class="am-footer"><div class="am-wrap am-footer__grid"><div><img :src="settings.logoLight" :alt="settings.brand||settings.name"><p>{{settings.description}}</p></div><div><strong>Contactos</strong><p><template v-for="phone in settings.phones||[]" :key="phone"><a :href="phoneHref(phone)">{{phone}}</a><br></template><a v-if="settings.email" :href="`mailto:${settings.email}`">{{settings.email}}</a><br v-if="settings.email"><a v-if="settings.instagram" :href="settings.instagramUrl" target="_blank" rel="noopener">{{settings.instagram}}</a></p></div><div><strong>Presença</strong><p>{{(settings.locations||[]).join(' · ')}}</p><small>© {{year}} {{settings.name}}</small></div></div></footer></template>
